        private void HandleLotProductionSettings()
        {
            string lotName = (this.LotName ?? "").Trim();

            if (string.IsNullOrEmpty(lotName))
            {
                Report.Log(ReportLevel.Info, "OpenFile_FromProduction",
                    "LotName rong — skip LOT Settings, giu nguyen.");
                return;
            }

            Report.Log(ReportLevel.Info, "OpenFile_FromProduction",
                "Click BtnLotSettings de mo LOT Settings...");
            repo.InspectionRegionSettings.BtnLotSettings.Click();
            Delay.Milliseconds(500);

            if (!TryFindLotDialog(LOT_DIALOG_TIMEOUT_MS))
            {
                Report.Screenshot(repo.CCIMainWindow.Self, true);
                throw new Exception(string.Format(
                    "LOT Settings dialog khong xuat hien sau {0}ms.", LOT_DIALOG_TIMEOUT_MS));
            }
            Report.Log(ReportLevel.Success, "OpenFile_FromProduction",
                "LOT Settings dialog da mo.");

            Report.Log(ReportLevel.Info, "OpenFile_FromProduction",
                string.Format("Nhap LOT ID = '{0}'...", lotName));
            repo.KohyoungGUI1.TxtLotID.Click();
            Delay.Milliseconds(200);
            Keyboard.Press("{Home}");
            Delay.Milliseconds(100);
            Keyboard.Press("{Shift down}{End}{Shift up}");
            Delay.Milliseconds(100);
            Keyboard.Press("{Delete}");
            Delay.Milliseconds(200);
            Keyboard.Press(lotName);
            Report.Log(ReportLevel.Success, "OpenFile_FromProduction",
                string.Format("Da nhap LOT ID = '{0}'.", lotName));

            string qty = (this.InspectionQuantity ?? "").Trim();
            Keyboard.Press("{Tab}");
            Delay.Milliseconds(200);

            if (!string.IsNullOrEmpty(qty))
            {
                int qtyNum;
                if (!int.TryParse(qty, out qtyNum) || qtyNum <= 0)
                    throw new ArgumentException(string.Format(
                        "InspectionQuantity = '{0}' khong hop le. Can so nguyen duong.", qty));

                Report.Log(ReportLevel.Info, "OpenFile_FromProduction",
                    string.Format("Nhap Planned Qty = '{0}'...", qty));
                Keyboard.Press("{Home}");
                Delay.Milliseconds(100);
                Keyboard.Press("{Shift down}{End}{Shift up}");
                Delay.Milliseconds(100);
                Keyboard.Press("{Delete}");
                Delay.Milliseconds(200);
                Keyboard.Press(qty);
                Report.Log(ReportLevel.Success, "OpenFile_FromProduction",
                    string.Format("Da nhap Planned Qty = '{0}'.", qty));
            }
            else
            {
                Report.Log(ReportLevel.Info, "OpenFile_FromProduction",
                    "InspectionQuantity rong — giu nguyen Planned Qty mac dinh.");
            }

            Report.Log(ReportLevel.Info, "OpenFile_FromProduction",
                "Click BtnLotApply...");
            repo.KohyoungGUI1.BtnLotApply.Click();
            Delay.Milliseconds(1000);

            if (!TryFindLotDialog(LOT_DIALOG_POLL_MS))
            {
                Report.Log(ReportLevel.Success, "OpenFile_FromProduction",
                    "LOT Settings da dong sau Apply.");
                return;
            }

            var sw = System.Diagnostics.Stopwatch.StartNew();
            while (sw.ElapsedMilliseconds < LOT_DIALOG_TIMEOUT_MS)
            {
                if (!TryFindLotDialog(LOT_DIALOG_POLL_MS))
                {
                    sw.Stop();
                    Report.Log(ReportLevel.Success, "OpenFile_FromProduction",
                        string.Format("LOT Settings da dong ({0}ms).", sw.ElapsedMilliseconds));
                    return;
                }
            }

            sw.Stop();
            Report.Screenshot(repo.CCIMainWindow.Self, true);
            Report.Log(ReportLevel.Error, "OpenFile_FromProduction",
                string.Format("LOT Settings KHONG dong sau {0}ms. "
                    + "Co the LOT ID = '{1}' da ton tai (loi 'already exists') "
                    + "hoac loi khac. Xem screenshot.", LOT_DIALOG_TIMEOUT_MS, lotName));
            throw new Exception(string.Format(
                "LOT Settings dialog khong dong sau {0}ms. LOT ID = '{1}' co the da ton tai.",
                LOT_DIALOG_TIMEOUT_MS, lotName));
        }

        private void ClickRadioAndVerify(RadioButton radio, string radioName)
        {
            const int VERIFY_TIMEOUT_MS = 3000;
            const int VERIFY_POLL_MS = 500;

            radio.EnsureVisible();

            if (!radio.Element.Enabled)
            {
                Report.Screenshot(repo.InspectionRegionSettings.Self, true);
                throw new Exception(string.Format(
                    "{0} disabled — dialog co the dang loading.", radioName));
            }

            Report.Log(ReportLevel.Info, "OpenFile_FromProduction",
                string.Format("Click {0}...", radioName));
            radio.Click();

            var sw = System.Diagnostics.Stopwatch.StartNew();
            while (sw.ElapsedMilliseconds < VERIFY_TIMEOUT_MS)
            {
                if (radio.Checked)
                {
                    sw.Stop();
                    Report.Log(ReportLevel.Success, "OpenFile_FromProduction",
                        string.Format("{0} da duoc chon ({1}ms).", radioName, sw.ElapsedMilliseconds));
                    return;
                }
                Delay.Milliseconds(VERIFY_POLL_MS);
            }

            sw.Stop();
            Report.Screenshot(repo.InspectionRegionSettings.Self, true);
            throw new Exception(string.Format(
                "{0} khong duoc chon sau khi click ({1}ms).", radioName, VERIFY_TIMEOUT_MS));
        }

        private void ClickApplyWithFallback()
        {
            const int DIALOG_LOADING_TIMEOUT_MS = 60000;
            const int DIALOG_POLL_MS = 2000;
            const int DIALOG_LOG_INTERVAL_MS = 10000;

            // Strategy 1: Native WPF Apply — Adapter.Click
            try
            {
                Report.Log(ReportLevel.Info, "OpenFile_FromProduction",
                    "Strategy 1: Native WPF Apply.Click()...");
                repo.InspectionRegionSettings.BtnApplyProductionPresetting.Click();
                Delay.Milliseconds(500);
                if (WaitForDialogClose("Strategy 1 — Native WPF", DIALOG_LOADING_TIMEOUT_MS, DIALOG_POLL_MS, DIALOG_LOG_INTERVAL_MS))
                    return;
            }
            catch (Exception ex)
            {
                Report.Log(ReportLevel.Warn, "OpenFile_FromProduction",
                    string.Format("Strategy 1 exception: {0}", ex.Message));
            }

            // Strategy 2: Native WPF Apply — Focus + Space
            try
            {
                Report.Log(ReportLevel.Info, "OpenFile_FromProduction",
                    "Strategy 2: Focus + Space...");
                repo.InspectionRegionSettings.BtnApplyProductionPresetting.Focus();
                Delay.Milliseconds(200);
                Keyboard.Press("{Space}");
                Delay.Milliseconds(500);
                if (WaitForDialogClose("Strategy 2 — Focus+Space", DIALOG_LOADING_TIMEOUT_MS, DIALOG_POLL_MS, DIALOG_LOG_INTERVAL_MS))
                    return;
            }
            catch (Exception ex)
            {
                Report.Log(ReportLevel.Warn, "OpenFile_FromProduction",
                    string.Format("Strategy 2 exception: {0}", ex.Message));
            }

            // Strategy 3: UIA BtnApplyProductionPresetting — Click
            try
            {
                Report.Log(ReportLevel.Info, "OpenFile_FromProduction",
                    "Strategy 3: UIA BtnApplyProductionPresetting.Click()...");
                if (repo.InspectionRegionSettings.BtnApplyProductionPresettingInfo.Exists(2000))
                {
                    repo.InspectionRegionSettings.BtnApplyProductionPresetting.Click();
                    Delay.Milliseconds(500);
                    if (WaitForDialogClose("Strategy 3 — UIA", DIALOG_LOADING_TIMEOUT_MS, DIALOG_POLL_MS, DIALOG_LOG_INTERVAL_MS))
                        return;
                }
                else
                {
                    Report.Log(ReportLevel.Warn, "OpenFile_FromProduction",
                        "Strategy 3: BtnApplyProductionPresetting khong tim thay.");
                }
            }
            catch (Exception ex)
            {
                Report.Log(ReportLevel.Warn, "OpenFile_FromProduction",
                    string.Format("Strategy 3 exception: {0}", ex.Message));
            }

            // Strategy 4: Native WPF Apply — Coordinate click via ScreenRectangle
            try
            {
                Report.Log(ReportLevel.Info, "OpenFile_FromProduction",
                    "Strategy 4: Coordinate click via ScreenRectangle...");
                var rect = repo.InspectionRegionSettings.BtnApplyProductionPresetting.Element.ScreenRectangle;
                int cx = rect.Location.X + rect.Width / 2;
                int cy = rect.Location.Y + rect.Height / 2;
                Mouse.MoveTo(new Point(cx, cy));
                Mouse.Click();
                Delay.Milliseconds(500);
                if (WaitForDialogClose("Strategy 4 — Coordinate", DIALOG_LOADING_TIMEOUT_MS, DIALOG_POLL_MS, DIALOG_LOG_INTERVAL_MS))
                    return;
            }
            catch (Exception ex)
            {
                Report.Log(ReportLevel.Warn, "OpenFile_FromProduction",
                    string.Format("Strategy 4 exception: {0}", ex.Message));
            }

            Report.Screenshot(repo.CCIMainWindow.Self, true);
            throw new Exception("Tat ca 4 strategy click Apply deu that bai. Dialog van con mo.");
        }

        private bool WaitForDialogClose(string strategyName, int timeoutMs, int pollMs, int logIntervalMs)
        {
            var sw = System.Diagnostics.Stopwatch.StartNew();
            long lastLogMs = 0;

            while (sw.ElapsedMilliseconds < timeoutMs)
            {
                if (!repo.InspectionRegionSettings.SelfInfo.Exists(pollMs))
                {
                    sw.Stop();
                    Report.Log(ReportLevel.Success, "OpenFile_FromProduction",
                        string.Format("Buoc 6 OK: Apply clicked ({0}). Dialog dong sau {1}ms.",
                            strategyName, sw.ElapsedMilliseconds));
                    return true;
                }

                long elapsed = sw.ElapsedMilliseconds;
                if (elapsed - lastLogMs >= logIntervalMs)
                {
                    lastLogMs = elapsed;
                    Report.Log(ReportLevel.Info, "OpenFile_FromProduction",
                        string.Format("{0}: dialog van mo, dang cho app load... ({1}/{2}s)",
                            strategyName, elapsed / 1000, timeoutMs / 1000));
                }
            }

            sw.Stop();
            Report.Log(ReportLevel.Warn, "OpenFile_FromProduction",
                string.Format("{0}: dialog van con mo sau {1}ms.", strategyName, timeoutMs));
            return false;
        }

